#!/bin/sh
# Downloads the publicly available corpora used by the evaluation into ../data
# (relative to this script's parent directory, i.e. evaluation/data):
#   NIPS (UCI bag of words), Reuters-21578 (Distribution 1.0, or the NLTK copy), 20 Newsgroups (duplicates removed),
#   the AP extract of Blei's lda-c and OHSUMED (ohscal, Forman's text data sets). Not fetched: the TREC AP corpus
#   (licensed), Online Retail (UCI, xlsx: export it as ';' separated CSV), Ta-Feng, US supermarket, NYT (1 GB).
# The synthetic TWC corpus needs no download, it is generated by the evaluation code.
# Existing data is not downloaded again.
set -eu

DATA="${1:-$(cd "$(dirname "$0")/.." && pwd)/data}"
mkdir -p "$DATA"

fetch() { # url, output file
  echo "Downloading $1"
  curl -fL --retry 3 -o "$2" "$1"
}

if [ ! -f "$DATA/nips/docword.nips.txt" ]; then
  mkdir -p "$DATA/nips"
  base=https://archive.ics.uci.edu/ml/machine-learning-databases/bag-of-words
  fetch "$base/docword.nips.txt.gz" "$DATA/nips/docword.nips.txt.gz"
  gunzip -f "$DATA/nips/docword.nips.txt.gz"
  fetch "$base/vocab.nips.txt" "$DATA/nips/vocab.nips.txt"
fi

if [ ! -d "$DATA/reuters21578" ] && [ ! -f "$DATA/reuters-nltk/reuters.zip" ]; then
  if fetch https://archive.ics.uci.edu/ml/machine-learning-databases/reuters21578-mld/reuters21578.tar.gz "$DATA/reuters21578.tar.gz" ||
     fetch http://kdd.ics.uci.edu/databases/reuters21578/reuters21578.tar.gz "$DATA/reuters21578.tar.gz"; then
    mkdir -p "$DATA/reuters21578"
    tar -xzf "$DATA/reuters21578.tar.gz" -C "$DATA/reuters21578"
    rm "$DATA/reuters21578.tar.gz"
  else
    # Fallback: the ApteMod version distributed with NLTK (same ModApte documents, one text file each).
    mkdir -p "$DATA/reuters-nltk"
    fetch https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/reuters.zip "$DATA/reuters-nltk/reuters.zip"
  fi
fi

if [ ! -d "$DATA/20news-18828" ]; then
  fetch http://qwone.com/~jason/20Newsgroups/20news-18828.tar.gz "$DATA/20news-18828.tar.gz"
  tar -xzf "$DATA/20news-18828.tar.gz" -C "$DATA"
  rm "$DATA/20news-18828.tar.gz"
fi

echo "Data is in $DATA"

if [ ! -f "$DATA/ap/ap.txt" ]; then
  # AP extract (2246 articles) of Blei's lda-c distribution
  fetch http://www.cs.columbia.edu/~blei/lda-c/ap.tgz "$DATA/ap.tgz" &&
    tar -xzf "$DATA/ap.tgz" -C "$DATA" && rm -f "$DATA/ap.tgz"
fi

if [ ! -f "$DATA/ohsumed/ohscal.wc.arff" ]; then
  # OHSUMED (ohscal) from Forman's 19 text data sets (sparse ARFF, weka datasets page)
  mkdir -p "$DATA/ohsumed"
  if fetch "https://sourceforge.net/projects/weka/files/datasets/text-datasets/19MclassTextWc.zip/download" "$DATA/19MclassTextWc.zip"; then
    unzip -o -j "$DATA/19MclassTextWc.zip" "*ohscal.wc.arff" -d "$DATA/ohsumed" && rm -f "$DATA/19MclassTextWc.zip"
  fi
fi
